240 /** Print an error the way a CLI should — message + stack, no JSON noise. */
241 function reportFatal(err: unknown): never {
242   process.stderr.write((err instanceof Error ? (err.stack ?? err.message) : String(err)) + "\n");
243   process.exit(1);
244 }
