47 function lookupPricing(model: string): { pricing: ModelPricing; known: boolean } {
48   // Try OpenRouter snapshot lookup for models with vendor/ prefix
49   if (model.includes("/")) {
50     const hit = findOpenRouterModel(model);
51     if (hit && (hit.inputPricePerMillion > 0 || hit.outputPricePerMillion > 0)) {
52       return openRouterPricing(hit);
53     }
54   }
55   // Also try OpenRouter for short names (e.g. "deepseek-v4-flash" → "deepseek/deepseek-v4-flash")
56   // by matching on the model part after the slash
57   const orHit =
58     findOpenRouterModel(`deepseek/${model}`) ??
59     findOpenRouterModel(`openai/${model}`) ??
60     findOpenRouterModel(`anthropic/${model}`);
61   if (orHit && (orHit.inputPricePerMillion > 0 || orHit.outputPricePerMillion > 0)) {
62     return openRouterPricing(orHit);
63   }
64   const canonical = getCanonicalName(model);
65   const hit = MODEL_PRICING[canonical] ?? MODEL_PRICING[model];
66   if (hit) return { pricing: hit, known: true };
67   return { pricing: DEFAULT_PRICING, known: false };
68 }
