 4 function isOwnedSummary(value: unknown, sessionId: string): value is UsageSummary {
 5   if (!value || typeof value !== "object" || Array.isArray(value)) return false;
 6   const summary = value as UsageSummary;
 7   return (
 8     summary.version === 1 &&
 9     summary.scope === "session" &&
10     summary.sessionId === sessionId &&
11     summary.includesChildren === true &&
12     typeof summary.partial === "boolean" &&
13     Number.isFinite(summary.knownEstimatedCostUsd) &&
14     summary.knownEstimatedCostUsd >= 0 &&
15     Number.isSafeInteger(summary.unknownCostRequests) &&
16     summary.unknownCostRequests >= 0 &&
17     Number.isSafeInteger(summary.totalTokens) &&
18     summary.totalTokens >= 0
19   );
20 }
